package Exception_Handling;public class multiple_exceptions {    int []arr={20,30,40,50};    int []arr1={2,3,0,5};    String a=null;    public void divide()    {        for (int i = 0; i < arr.length; i++) {            try{                System.out.println(arr[i]/arr1[i]);            }            catch(ArithmeticException e){                System.out.println("If any no. divide by 0 it will give exceptions");                System.out.println(e);            }        }    }    public void null_exceptions(){        try{            System.out.println(a.length());        }        catch(NullPointerException e){            System.out.println(e);        }        catch(Exception e){            System.out.println(e);        }        finally {            System.out.println("Hello");        }    }    public static void main(String[] args) {        multiple_exceptions e1=new multiple_exceptions();        e1.divide();        e1.null_exceptions();    }}